message.content:
{
  "technical_and_design_decisions": [
    "Implement RabbitMQ resource cleanup in the StreamPlugin on container side, triggered by `stream destroy --clean`, using Spring AMQP RabbitAdmin and RabbitManagementTemplate for exchanges/bindings.",
    "Expose a per-stream/per-module Spring Integration error channel (e.g., xd.<stream>.<module>.error) that captures exceptions and allows user subscription.",
    "For security (U3), limit scope to a spike: research Spring Security/Boot OOTB and produce design doc; recommended approach is externalized credential config and auto-configured security for REST endpoints, shell, and UI.",
    "Create a new http-mvc source module based on Spring MVC with embedded Tomcat, supporting content-type negotiation and full header mapping, reusing existing HTTP module configuration.",
    "Implement status change detection via both client-side polling API and server-side event propagation (Spring events + SSE/WebSocket) from containers to admin and UI.",
    "Implement SFTP source using Spring Integration SFTP adapter with embedded test SFTP server for integration tests.",
    "Implement ElasticSearch sink using Spring Data Elasticsearch (or REST client) with configurable index/type and bulk indexing.",
    "Document available property keys (e.g., ${xd.stream.name}, ${xd.job.name}, ${xd.container.id}) in the user guide."
  ],
  "assumptions": [
    "The increment targets Spring XD codebase with a modern Spring Boot/Spring Integration stack; build environment and dependencies are already available.",
    "U3 is limited to research and design spike as explicitly stated; full security implementation is out of scope for this increment.",
    "For U6, both the minimum client-side polling and the ideal server-side event propagation are implemented.",
    "Developer has moderate prior experience with Spring XD and Spring technologies, so estimates exclude long learning curves.",
    "Integration tests use embedded or test-container instances for RabbitMQ, Elasticsearch, and SFTP; no production deployment effort included.",
    "Effort estimates are in workdays (8-hour days) for a single developer and include coding, unit/integration testing, and basic documentation."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Detailed design and architecture alignment",
      "activity_description": "Analyze all user stories, define overall technical approach, and align with Spring XD architecture (module/plugin structure, event bus, REST API).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "U1: Stream destroy cleanup implementation",
      "activity_description": "Implement optional `--clean` flag for stream destroy in StreamPlugin; clean up RabbitMQ queues/topics/exchanges using RabbitAdmin/RabbitManagementTemplate, handling last consumer and fanout exchanges.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "U2: Per-module error channel",
      "activity_description": "Add dedicated error channel per stream/module to capture exceptions and allow users to tap into failures; implement routing and configuration.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "U3: Security spike (research & design)",
      "activity_description": "Research Spring Security and Spring Boot OOTB features; design approach for securing REST endpoints, DSL shell, and Admin UI; document developer experience and configuration model.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5",
      "activity_name": "U4: Document property keys",
      "activity_description": "Write user documentation for available keys such as ${xd.stream.name}, ${xd.job.name}, ${xd.container.id}.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A6",
      "activity_name": "U5: MVC-aware HTTP source module",
      "activity_description": "Develop new http-mvc source module with embedded Tomcat, Spring MVC, richer content-type support, and full header mapping; include unit/integration tests.",
      "most_likely_effort": 6.5
    },
    {
      "activity_id": "A7",
      "activity_name": "U6: Status change notification",
      "activity_description": "Implement client-side polling API and server-side event propagation (containers to admin to UI) for stream/job status changes using Spring events and SSE/WebSocket; include tests.",
      "most_likely_effort": 6.5
    },
    {
      "activity_id": "A8",
      "activity_name": "U7: SFTP source module",
      "activity_description": "Implement SFTP source module using Spring Integration SFTP adapter, including test infrastructure (embedded SFTP server) and integration tests.",
      "most_likely_effort": 5.5
    },
    {
      "activity_id": "A9",
      "activity_name": "U8: ElasticSearch sink module",
      "activity_description": "Implement native ElasticSearch sink module for real-time indexing/aggregation with configurable options; include integration tests.",
      "most_likely_effort": 5.5
    },
    {
      "activity_id": "A10",
      "activity_name": "Final integration, build, and documentation review",
      "activity_description": "Integrate all modules, verify build, perform cross-feature integration testing, and review documentation.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 42.5
  }
}

